// Built on first use so the cost is paid once per server instance, not at
// module load.
let cache: Set<string> | null = null;

/** True if the token is a known Czech/Slovak name or place (diacritic-free). */
export function isCzechProperNoun(token: string): boolean {
  if (!cache) cache = new Set(RAW.split("\n"));
  return cache.has(token);
}
